c=json.loads((raw/'contract.json').read_text());status=json.loads((raw/'status.json').read_text());contexts=json.loads((a.run/'contexts.json').read_text());cases=json.loads((raw.parent/'cases.json').read_text());archive=np.load(raw/'trajectory.npz');data={k:archive[k] for k in archive.files};archive.close();index=[];case_metrics={};route=np.load(Path(spec['source_bundle'])/'route.npz');cfg=json.loads(Path(spec['base_sweep_config']).read_text());colors=['#0072B2','#D55E00','#009E73','#CC79A7','#8B6500'];palette={0:colors[0],.25:colors[1],.5:colors[2],.75:colors[3],1:colors[4]}
