 xy.set(xlabel='World x (m)',ylabel='World y (m)');xy.set_aspect('equal',adjustable='datalim');xy.legend(fontsize=7);per.set(xlabel='Policy step',ylabel='Native preference-weighted reward');cumulative.set(xlabel='Policy step',ylabel='Cumulative native reward');speed.set(xlabel='Time (s)',ylabel='True speed error (m/s)')
